public sealed class CalculatePayableTotal
{
    public int For(int subtotalCents, LoyaltyTier loyaltyTier)
    {
        var ratePercent = LoyaltyDiscountPolicy.EffectiveRatePercent(loyaltyTier, subtotalCents);
        var discountCents = (int)((long)subtotalCents * ratePercent / 100);
        return subtotalCents - discountCents;
    }
}
