namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MaxRatePercent = 10;

    public static int EffectiveRatePercent(LoyaltyTier tier, int subtotalCents)
    {
        var baseRate = tier switch
        {
            LoyaltyTier.Green => 5,
            LoyaltyTier.Gold => 7,
            LoyaltyTier.Platinum => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(tier)),
        };
        var bonus = subtotalCents >= 20_000 ? 3 : subtotalCents >= 5_000 ? 1 : 0;
        return Math.Min(baseRate + bonus, MaxRatePercent);
    }
}
